### 3. Implementación de RPC Transaccional con Control de Concurrencia (ACID)

La creación de la comanda desde la preventa debe realizarse atómicamente para evitar estados huérfanos o discrepancias en la cocina.

```sql
CREATE OR REPLACE FUNCTION public.rpc_confirmar_preventa_y_generar_comanda(
    p_preventa_id UUID,
    p_observaciones TEXT DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_tenant_id UUID;
    v_sucursal_id UUID;
    v_comanda_id UUID;
    v_user_tenant UUID;
BEGIN
    -- Obtener y validar el tenant_id del JWT actual
    v_user_tenant := (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid;

    -- Bloqueo pesimista de la preventa para evitar doble confirmación concurrente
    SELECT tenant_id, sucursal_id 
    INTO v_tenant_id, v_sucursal_id
    FROM public.preventas
    WHERE id = p_preventa_id AND tenant_id = v_user_tenant
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Preventa no encontrada o acceso denegado por políticas Multi-Tenant.';
    END IF;

    -- Actualizar estado de preventa
    UPDATE public.preventas
    SET estado = 'confirmada', updated_at = NOW()
    WHERE id = p_preventa_id;

    -- Crear la comanda vinculada
    INSERT INTO public.comandas (tenant_id, sucursal_id, preventa_id, estado, observaciones)
    VALUES (v_tenant_id, v_sucursal_id, p_preventa_id, 'pendiente', p_observaciones)
    RETURNING id INTO v_comanda_id;

    -- Copiar ítems de la preventa hacia detalle_comandas (Asumiendo tabla preventa_detalles existente)
    INSERT INTO public.detalle_comandas (tenant_id, comanda_id, producto_id, cantidad, notas_item)
    SELECT 
        v_tenant_id, 
        v_comanda_id, 
        pd.producto_id, 
        pd.cantidad, 
        pd.notas
    FROM public.preventa_detalles pd
    WHERE pd.preventa_id = p_preventa_id;

    RETURN v_comanda_id;
END;
$$;
```

