### 4. Configuración del Cliente Frontend (React 18 + TypeScript)

Para consumir los canales en tiempo real filtrados por sucursal y tenant de forma segura, se implementa el siguiente hook de conexión utilizando el SDK de Supabase:

```typescript
import { useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';

// Instancia tipada del cliente Supabase para maestro_ERP_Pezcaderia
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
export const supabase = createClient(supabaseUrl, supabaseAnonKey);

interface UseComandasRealtimeProps {
  sucursalId: string;
  onNuevaComanda: (payload: any) => void;
  onActualizacionComanda: (payload: any) => void;
}

export const useComandasRealtime = ({
  sucursalId,
  onNuevaComanda,
  onActualizacionComanda,
}: UseComandasRealtimeProps) => {
  useEffect(() => {
    // Canal único por sucursal para aislamiento físico/lógico
    const channelName = `comandas_sucursal_${sucursalId}`;

    const channel = supabase
      .channel(channelName)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'comandas',
          filter: `sucursal_id=eq.${sucursalId}`,
        },
        (payload) => {
          onNuevaComanda(payload.new);
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'comandas',
          filter: `sucursal_id=eq.${sucursalId}`,
        },
        (payload) => {
          onActualizacionComanda(payload.new);
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log(`Canal Realtime activo para sucursal: ${sucursalId}`);
        }
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }, [sucursalId, onNuevaComanda, onActualizacionComanda]);
};
```

